package com.vandorlabs.neoforge.copier;

import com.vandorlabs.copier.core.CopySettings;
import com.vandorlabs.neoforge.inventory.NativeInventoryItems;
import com.vandorlabs.neoforge.surface.*;
import com.vandorlabs.neoforge.transfer.*;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.nbt.*;
import net.minecraft.world.item.ItemStack;

/** Immutable decoded economy/layout receipt. No live world, tile, inventory or player is retained. */
final class NativeCopyReceipt {
    final CopySettings settings;final NativeSurfaceLayout inputPad,outputPad;
    final NativeSurfacePrism sourceVolume,targetVolume;
    final NativeTransferSnapshot source,costSource;
    final NativeCopySupply supply;final List<NativeCopyMaterials.Need> needs;
    private final ItemStack chip;final BlockPos chipMount;
    private NativeCopyReceipt(CopySettings settings,NativeSurfaceLayout inputPad,NativeSurfaceLayout outputPad,NativeSurfacePrism sourceVolume,NativeSurfacePrism targetVolume,NativeTransferSnapshot source,NativeTransferSnapshot costSource,NativeCopySupply supply,List<NativeCopyMaterials.Need> needs,ItemStack chip,BlockPos chipMount){this.settings=settings;this.inputPad=inputPad;this.outputPad=outputPad;this.sourceVolume=sourceVolume;this.targetVolume=targetVolume;this.source=source;this.costSource=costSource;this.supply=supply;this.needs=List.copyOf(needs);this.chip=chip.copy();this.chipMount=chipMount;}
    ItemStack chip(){return chip.copy();}
    static CompoundTag write(NativeCopyControllerEntity root,NativeCopyPlan plan,HolderLookup.Provider registries){
        var tag=new CompoundTag();tag.putInt("Schema",1);tag.put("Settings",NativeCopySettingsData.write(plan.settings));tag.put("OutputPad",root.output().save());tag.put("TargetBounds",bounds(plan.targetVolume));tag.put("CostSource",plan.costSource.write());tag.put("Needs",NativeCopyMaterials.write(plan.materials,registries));if(plan.supply!=null)tag.put("Supply",plan.supply.write());
        if(plan.settings.chip){tag.putLong("ChipMount",plan.chipPosition().asLong());tag.put("Chip",plan.chip().save(registries));}else{tag.put("InputPad",root.input().save());tag.put("InputSource",plan.input.write());tag.put("SourceBounds",bounds(plan.sourceVolume));}return tag;
    }
    private static CompoundTag bounds(NativeSurfacePrism volume){var tag=new CompoundTag();tag.putLong("Min",volume.min().asLong());tag.putLong("Max",volume.max().asLong());return tag;}
    private static NativeSurfacePrism bounds(CompoundTag tag){if(!tag.getAllKeys().equals(Set.of("Min","Max"))||!tag.contains("Min",Tag.TAG_LONG)||!tag.contains("Max",Tag.TAG_LONG))throw new IllegalArgumentException("Copy volume receipt");return new NativeSurfacePrism(BlockPos.of(tag.getLong("Min")),BlockPos.of(tag.getLong("Max")));}
    static NativeCopyReceipt read(HolderLookup.Provider registries,NativeCellTransactions.Header header,NativeTransferSnapshot before,NativeTransferSnapshot after,Set<BlockPos> held,CompoundTag raw){
        if(!raw.contains("Schema",Tag.TAG_INT)||raw.getInt("Schema")!=1||!raw.contains("Settings",Tag.TAG_COMPOUND)||!raw.contains("OutputPad",Tag.TAG_COMPOUND)||!raw.contains("TargetBounds",Tag.TAG_COMPOUND)||!raw.contains("CostSource",Tag.TAG_COMPOUND)||!raw.contains("Needs",Tag.TAG_LIST))throw new IllegalArgumentException("Copy receipt schema");var settings=NativeCopySettingsData.read(raw.getCompound("Settings"));var fields=new HashSet<>(Set.of("Schema","Settings","OutputPad","TargetBounds","CostSource","Needs"));if(!header.creative())fields.add("Supply");fields.addAll(settings.chip?Set.of("ChipMount","Chip"):Set.of("InputPad","InputSource","SourceBounds"));if(!raw.getAllKeys().equals(fields))throw new IllegalArgumentException("Unknown or missing Copy receipt fields");
        var output=NativeSurfaceLayout.read(raw.getCompound("OutputPad"),header.root(),true);var target=bounds(raw.getCompound("TargetBounds"));if(!target.equals(NativeSurfacePrism.of(output,settings.height))||!held.containsAll(output.cells))throw new IllegalArgumentException("Copy output footprint recipe");var cost=NativeTransferSnapshot.read(registries,raw.getCompound("CostSource"),NativeCopyPlan.LIMITS,state->Map.of());var needs=NativeCopyMaterials.read(raw.getList("Needs",Tag.TAG_COMPOUND),registries);var supply=header.creative()?null:NativeCopySupply.read(registries,raw.getCompound("Supply"));if(header.creative()&&!needs.isEmpty())throw new IllegalArgumentException("Creative copy cannot withdraw materials");if(supply!=null){supply.validateCost(needs);if(!held.containsAll(supply.positions()))throw new IllegalArgumentException("Material receipt outside held footprint");}
        var actualBefore=new LinkedHashMap<BlockPos,NativeRawCell>();var actualAfter=new LinkedHashMap<BlockPos,NativeRawCell>();for(var cell:before.cells())actualBefore.put(cell.pos,cell);for(var cell:after.cells())actualAfter.put(cell.pos,cell);var expectedBefore=new LinkedHashMap<BlockPos,NativeRawCell>();var expectedAfter=new LinkedHashMap<BlockPos,NativeRawCell>();if(supply!=null){for(var cell:supply.before())expectedBefore.put(cell.pos,cell);for(var cell:supply.after())expectedAfter.put(cell.pos,cell);}
        for(var pos:target.cells()){var empty=new NativeRawCell(pos,net.minecraft.world.level.block.Blocks.AIR.defaultBlockState(),null,NativeCopyPlan.LIMITS.tileBytes());if(expectedBefore.put(pos,empty)!=null||expectedAfter.put(pos,empty)!=null||!held.contains(pos))throw new IllegalArgumentException("Copy output overlaps material owner or missing reservation");}
        for(var cell:cost.cells()){if(cell.state.isAir()||!target.contains(cell.pos))throw new IllegalArgumentException("Copy cost cell outside output");expectedAfter.put(cell.pos,NativeCopyChannels.increment(cell,settings.increment));}
        if(!actualBefore.keySet().equals(expectedBefore.keySet())||!actualAfter.keySet().equals(expectedAfter.keySet()))throw new IllegalArgumentException("Copy publication cell coverage");for(var entry:expectedBefore.entrySet())if(!entry.getValue().identical(actualBefore.get(entry.getKey()))||!expectedAfter.get(entry.getKey()).identical(actualAfter.get(entry.getKey())))throw new IllegalArgumentException("Copy publication differs from typed economy recipe");
        NativeSurfaceLayout input=null;NativeSurfacePrism from=null;NativeTransferSnapshot source=null;ItemStack chip=ItemStack.EMPTY;BlockPos mount=null;
        if(settings.chip){if(!raw.contains("ChipMount",Tag.TAG_LONG)||!raw.contains("Chip",Tag.TAG_COMPOUND))throw new IllegalArgumentException("Copy construction chip receipt");mount=BlockPos.of(raw.getLong("ChipMount"));if(header.root().distManhattan(mount)!=1||!held.contains(mount))throw new IllegalArgumentException("Copy construction mount footprint");chip=NativeInventoryItems.modern(raw.getCompound("Chip"),registries);if(chip.getCount()!=1||!com.vandorlabs.neoforge.screen.NativeChipJournal.vehicle(chip))throw new IllegalArgumentException("Copy construction chip identity");}
        else{input=NativeSurfaceLayout.read(raw.getCompound("InputPad"),header.root(),true);from=bounds(raw.getCompound("SourceBounds"));if(!from.equals(NativeSurfacePrism.of(input,settings.height))||input.geometry.width!=output.geometry.width||input.geometry.height!=output.geometry.height||input.normal!=output.normal||from.bounds().intersects(target.bounds())||!held.containsAll(input.cells))throw new IllegalArgumentException("Copy paired-pad recipe");source=NativeTransferSnapshot.read(registries,raw.getCompound("InputSource"),NativeCopyPlan.LIMITS,state->Map.of());if(source.cells().size()!=from.cells().size())throw new IllegalArgumentException("Copy input prism coverage");var covered=new HashSet<BlockPos>();for(var cell:source.cells())if(!from.contains(cell.pos)||!held.contains(cell.pos)||!covered.add(cell.pos))throw new IllegalArgumentException("Copy source outside exact prism");}
        var receipt=new NativeCopyReceipt(settings,input,output,from,target,source,cost,supply,needs,chip,mount);receipt.validateDerivation(registries,header,held);return receipt;
    }
    private void validateDerivation(HolderLookup.Provider registries,NativeCellTransactions.Header header,Set<BlockPos> held){
        var rawSource=new ArrayList<NativeRawCell>();
        if(settings.chip){var design=NativeBlueprintDesign.read(chip,registries);for(var cell:design.cells){var tag=cell.tile();if(tag!=null){tag.putInt("x",cell.offset.getX());tag.putInt("y",cell.offset.getY());tag.putInt("z",cell.offset.getZ());}rawSource.add(new NativeRawCell(cell.offset,cell.state,tag,NativeCopyPlan.LIMITS.tileBytes()));}}
        else for(var cell:source.cells())if(!cell.state.isAir())rawSource.add(cell);
        if(rawSource.isEmpty()||rawSource.size()!=costSource.cells().size())throw new IllegalArgumentException("Copy cost/source coverage");
        NativeCopyTiles.requireCompleteChests(rawSource);
        int[] extents={Integer.MAX_VALUE,Integer.MAX_VALUE,Integer.MAX_VALUE,Integer.MIN_VALUE,Integer.MIN_VALUE,Integer.MIN_VALUE};for(var cell:rawSource){var relative=settings.chip?cell.pos:cell.pos.subtract(sourceVolume.min());int[] p={relative.getX(),relative.getY(),relative.getZ()};for(int axis=0;axis<3;axis++){extents[axis]=Math.min(extents[axis],p[axis]);extents[axis+3]=Math.max(extents[axis+3],p[axis]);}}
        int[] target={targetVolume.min().getX(),targetVolume.min().getY(),targetVolume.min().getZ(),targetVolume.max().getX(),targetVolume.max().getY(),targetVolume.max().getZ()};int[] shift=com.vandorlabs.copier.core.CopyGeometry.center(extents,target,outputPad.normal.getAxis()==Direction.Axis.X?0:outputPad.normal.getAxis()==Direction.Axis.Y?1:2);
        for(int i=0;i<rawSource.size();i++){var cell=rawSource.get(i);var relative=settings.chip?cell.pos:cell.pos.subtract(sourceVolume.min());var destination=targetVolume.min().offset(relative).offset(shift[0],shift[1],shift[2]);if(!NativeCopyTiles.at(cell,destination).identical(costSource.cells().get(i)))throw new IllegalArgumentException("Copy cost is not the exact translated source");}
        var expectedHeld=new HashSet<BlockPos>();expectedHeld.add(header.root());expectedHeld.addAll(outputPad.cells);expectedHeld.addAll(targetVolume.cells());if(inputPad!=null){expectedHeld.addAll(inputPad.cells);expectedHeld.addAll(sourceVolume.cells());}if(supply!=null)expectedHeld.addAll(supply.positions());if(chipMount!=null)expectedHeld.add(chipMount);if(!expectedHeld.equals(held))throw new IllegalArgumentException("Copy reservation differs from typed recipe");
    }

}
